-- GENERATED by `wfj generate` from data/gossip/gossip-ee.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["ee0019f9c65ae2c3"] = { "Tutte le richieste per il mio lavoro devono essere fatte di persona dall'acquirente. Orwin mi chiede spesso di ripensarci, ma le mie priorità sono qui. Guardati intorno: molti di questi combattenti contano su di me per le loro armature.", "." },
  ["ee03bee81bda112d"] = { "Qui c'è abbastanza lavoro per un esercito di orchi, e quasi tutto posso farlo solo io. Comunque, c'è un compito per cui mi servirebbe una mano.", "." },
  ["ee10618e487b9ea2"] = { "Mi serve aiuto per sconfiggere i bracconieri Ombroseta.", "." },
  ["ee143be85c99991b"] = { "Salve! Sono <un/una> <Ladro/Ladra> in cerca di addestramento.", "." },
  ["ee16118c4f232f57"] = { "%s agita i baffi verso {name}.", "." },
  ["ee1a0f95884431b7"] = { "Noi diventiamo forti, mentre i nostri nemici sono circondati da nemici e indeboliti da attacchi continui.", "." },
  ["ee1efd776a4e55fc"] = { "Buongiorno a te, Nogg! Ho bisogno di addestramento.", "." },
  ["ee31ea4a122e7bf9"] = { "Mi hanno cresciuto ed educato per il servizio pubblico. Una voce che rappresentava il popolo. La mia abilità non stava nelle armi o nei mestieri, ma nelle parole e nella persuasione.", "." },
  ["ee33877d6ee64b58"] = { "Sissignore. Grazie, signore!", "." },
  ["ee3530f6e3b117c3"] = { "Ah, la ⟦Alterac Valley=Valle d'Alterac⟧, ne ho dei bei ricordi, te lo dico io. <sospira> Be', non posso venire con te, ma fammi fare bella figura lo stesso! Per arrivarci dovrai parlare con Glordrum Steelbeard alla Hall of Arms, qui a ⟦Ironforge=Forgiardente⟧.", "." },
  ["ee433e2435c16f9f"] = { "I tempi in cui viviamo sono mutevoli come i venti, {class}. È importante ricordare ciò che in questo mondo è vero e duraturo, e preservarlo. Tutto il resto è uno spreco.", "." },
  ["ee4a596ce4831051"] = { "Se vuoi dare la caccia ai naga, ti servirà tutto l'aiuto possibile. In fondo all'acqua puoi trovare delle fessure gorgoglianti che producono abbastanza bolle d'aria da permetterti di respirare sott'acqua. Avvicinati a nuoto per poter usare le bolle.", "." },
  ["ee4cc5e81b9daf15"] = { "Belm dice di pagare il conto o ti spacca la faccia.", "." },
  ["ee518672dd5eadc8"] = { "Non possiamo dormire ancora un po'?", "." },
  ["ee526cc3155172f1"] = { "Sciocco ingenuo. Le ⟦Burning Blade=Lame Ardenti⟧ SONO il ⟦Shadow Council=Concilio dell'Ombra⟧! Ci sono molti culti e organizzazioni sotto il dominio del Concilio, ma sono tutti solo estensioni della sua volontà. Sarò anche a capo delle ⟦Burning Blade=Lame Ardenti⟧, ma resto una pedina del Concilio quanto tu lo sei per me!\n\nGuarda la ⟦Searing Blade=Lama Rovente⟧: quasi tutti i suoi membri credono di stare diventando il prossimo gruppo emergente di potenti stregoni, destinato a sostituire il ⟦Shadow Council=Concilio dell'Ombra⟧.", "." },
  ["ee54c12e38d98b51"] = { "Ma salve, <cittadino/cittadina>. Mi chiamo Bluntnose, magistrato Bluntnose, per la precisione. Il mio compito è vegliare sul benessere di Thelsamar e, credimi, qui un altro paio di braccia forti fa sempre comodo!", "." },
  ["ee568d25b696f683"] = { "Controlla sempre due volte le misure prima di cominciare a tagliare il cuoio. Non possiamo permetterci di sprecare materiali.", "." },
  ["ee65043d955ed290"] = { "Parlami del ⟦Elementals Deck=Mazzo degli Elementali⟧.", "." },
  ["ee6a6b3d4033712c"] = { "Le tue abilità non bastano per imparare ciò che insegno. Prova piuttosto a parlare con Mak, laggiù. Lui può aiutarti finché non sarai <pronto/pronta> per lezioni più avanzate.", "." },
  ["ee6b9df4384ff2f8"] = { "No, davvero, continuo a non capire...", "." },
  ["ee6ca5a8b343d7bd"] = { "Sai usare le parole, signore supremo Saurfang.", "." },
  ["ee71aac8753129a9"] = { "Scatenerò la cavalleria al tuo comando, signore!", "." },
  ["ee71dfb3992bf634"] = { "Posso insegnarti a cucinare!", "." },
  ["ee7496c15b1a8c4f"] = { "Argh! Sei senza speranza!", "." },
  ["ee77eecd6a89cd58"] = { "Parlami della ⟦Glowing Shard=Scheggia Brillante⟧.", "." },
  ["ee7b1006128c700b"] = { "{name} ci viene addosso!", "." },
  ["ee813f8241a13d89"] = { "Frutta succosa in vendita!", "." },
  ["ee88b2c3ca9602d1"] = { "Bixi Wobblebonk, la maestra d'armi gnoma, si aggira in questa bottega. Insegna l'uso di balestre, pugnali e armi da lancio.\n\nWoo Ping, il maestro d'armi umano del Weller's Arsenal a ⟦Stormwind=Roccavento⟧, insegna l'uso di balestre, pugnali, spade a una e a due mani, armi in asta e bastoni.\n\nIlyenia Moonfire, la maestra d'armi elfa della notte, risiede alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧ a Darnassus, dove insegna l'uso di archi, pugnali, armi da pugno, bastoni e armi da lancio.", "." },
  ["ee8b1f50f72bfe2e"] = { "Ogni giorno diventa più grasso e più corrotto. Si sente la puzza che gli esce dal corpo. È sporco, e non intendo solo che ha bisogno di lavarsi.\n\nBasta chiacchiere da Hulfdan. Da dove vieni e come posso aiutarti, {class}?", "." },
  ["ee92bcd9b5eb1abd"] = { "Hai imparato bene, <figlio/figlia> <mio/mia>. Va' a ⟦Undercity=Sepulcra⟧ e cerca un fabbro di nome James Van Brunt. Potrà insegnarti molto di ciò che io non posso. So che passa il suo tempo vicino alla sala d'addestramento dei guerrieri, a forgiare le loro armi e armature.", "." },
  ["ee981e0941ae1a5c"] = { "Si sa che quell'eremita di Mallory ogni tanto prepara qualche pozione per la gente del posto. Ha un cottage sulle colline tra ⟦Stormwind=Roccavento⟧ e la ⟦Northshire=Contea del Nord⟧.", "." },
  ["eea1e375551055b5"] = { "Ecco un segnalatore per te, {name}. Devi tenerlo con te se vuoi trovare gli oggetti corrotti che ci serviranno.", "." },
  ["eea9435210a288bc"] = { "Un istruttore di classe", "." },
  ["eeb1d09f8a19dc1b"] = { "La risata di %s risuona di nuovo nelle sale di Blackwing.", "." },
  ["eeb256eb48b4e7b7"] = { "Di cosa stai parlando, mago?", "." },
  ["eebb4d82be606285"] = { "Se sei qui per salvare il mondo, sei nel posto giusto. Colui che non ha volto, il Dio del Sangue Hakkar, è stato riportato nel nostro mondo!", "." },
  ["eec5ba073b58ce7b"] = { "Il mio grande martello, Ironfel, è passato al nuovo capo architetto, Fineous Darkvire: un uomo dalle intenzioni spregevoli e di scarso talento.\n\nÈ qui che entri in gioco tu, {name}. Voglio che sia fermato. È troppo inetto per sfruttare il vero potere di Ironfel, ma se dopo di lui arrivasse qualcuno con l'abilità di usare Ironfel al massimo delle sue potenzialità, la distruzione che potrebbe causare con le sue creazioni sarebbe disastrosa per questo mondo.", "." },
  ["eec5d52f4de40bf5"] = { "Cos'è Atiesh?", "." },
  ["eece0a3c52fb1bb6"] = { "Dov'è l'anziano Nightwind?", "." },
  ["eee4addf320086c8"] = { "Si dice che a nord viva un potente mago umano; veglia su quelle terre per qualche ragione sconosciuta. Non ho mai fatto quel viaggio di persona, ma si dice che i visitatori siano i benvenuti e possano persino guadagnarsi il suo favore, se sono disposti a sbrigare delle commissioni per lui.", "." },
  ["eeeb56bf63adc9b0"] = { "%s e le sue forze d'invasione compaiono in mezzo a un tumultuoso incendio nel nord-ovest di ⟦Silithus=Silitus⟧.", "." },
  ["eef4b8c115655150"] = { "Ma che...", "." },
  ["eefa55b4c7e65f03"] = { "Eseguo gli ordini del Capoguerra senza fare domande. Io sono l'⟦Horde=Orda⟧.", "." },
  ["eefff896ff6f1f54"] = { "Quindi è per questo che sei <venuto/venuta>? Per cercare di reclamare ciò che è la ragione dell'esistenza dell'Alba e della rovina della Crociata? Con le tue parole riapri vecchie ferite, comandante!", "." },
})
